data.definition:
flowchart TD
  Start((User Goal)) --> Thought[Thought: "What do I need to know?"]
  Thought --> Action[Action: Call a tool]
  Action --> Observation[Observation: Tool output]
  Observation --> ThinkAgain[Think: "Does this answer the goal?"]
  ThinkAgain -->|No| Thought
  ThinkAgain -->|Yes| Final((Final Answer))

  style Thought fill:#ddf4ff,stroke:#0969da;
  style Action fill:#d1f3d8,stroke:#1a7f37;
  style Observation fill:#fff8c5,stroke:#9a6700;
  style ThinkAgain fill:#eddff8,stroke:#8250df;
